class Solution {
    public int minTrioDegree(int n, int[][] edges) {
        boolean[][] adj = new boolean[n + 1][n + 1];
        List<List<Integer>> nbr = new ArrayList<>();
        for (int i = 0; i <= n; i++) nbr.add(new ArrayList<>());
        int[] deg = new int[n + 1];
        for (int[] e : edges) {
            adj[e[0]][e[1]] = true;
            adj[e[1]][e[0]] = true;
            nbr.get(e[0]).add(e[1]);
            nbr.get(e[1]).add(e[0]);
            deg[e[0]]++;
            deg[e[1]]++;
        }
        int best = Integer.MAX_VALUE;
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            boolean uv = deg[u] <= deg[v];
            int src = uv ? u : v, dst = uv ? v : u;
            for (int w : nbr.get(src))
                if (adj[w][dst])
                    best = Math.min(best, deg[u] + deg[v] + deg[w] - 6);
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

